import java.util.*;

public class Main {
    enum ExchangeType { DIRECT, TOPIC, FANOUT }
    enum Decision { ACK, NACK_TO_DLX }

    record Message(String routingKey, String body) {}
    record PublishResult(int routed, boolean returned, boolean confirmed) {}

    static final class QueueBox {
        final String name;
        final Deque<Message> ready = new ArrayDeque<>();
        QueueBox dlq;
        QueueBox(String name) { this.name = name; }
        void enqueue(Message message) { ready.addLast(message); }
        void consume(Decision decision) {
            Message message = ready.removeFirst();
            if (decision == Decision.NACK_TO_DLX && dlq != null) {
                dlq.enqueue(message);
            }
        }
    }

    static final class Binding {
        final QueueBox queue;
        final String key;
        Binding(QueueBox queue, String key) { this.queue = queue; this.key = key; }
    }

    static final class Exchange {
        final String name;
        final ExchangeType type;
        final List<Binding> bindings = new ArrayList<>();
        Exchange(String name, ExchangeType type) { this.name = name; this.type = type; }
        void bind(QueueBox queue, String key) { bindings.add(new Binding(queue, key)); }
        PublishResult publish(Message message, boolean mandatory) {
            int routed = 0;
            for (Binding binding : bindings) {
                if (matches(binding.key, message.routingKey())) {
                    binding.queue.enqueue(message);
                    routed++;
                }
            }
            return new PublishResult(routed, mandatory && routed == 0, true);
        }
        private boolean matches(String bindingKey, String routingKey) {
            if (type == ExchangeType.FANOUT) return true;
            if (type == ExchangeType.DIRECT) return bindingKey.equals(routingKey);
            return topicMatches(bindingKey.split("\\."), routingKey.split("\\."), 0, 0);
        }
        private boolean topicMatches(String[] pattern, String[] words, int p, int w) {
            if (p == pattern.length) return w == words.length;
            if (pattern[p].equals("#")) {
                return topicMatches(pattern, words, p + 1, w)
                        || (w < words.length && topicMatches(pattern, words, p, w + 1));
            }
            if (w == words.length) return false;
            if (pattern[p].equals("*") || pattern[p].equals(words[w])) {
                return topicMatches(pattern, words, p + 1, w + 1);
            }
            return false;
        }
    }

    public static void main(String[] args) {
        QueueBox orderQueue = new QueueBox("order.q");
        QueueBox auditQueue = new QueueBox("audit.q");
        QueueBox deadLetterQueue = new QueueBox("order.dlq");
        orderQueue.dlq = deadLetterQueue;

        Exchange topic = new Exchange("domain.events", ExchangeType.TOPIC);
        topic.bind(orderQueue, "order.created");
        topic.bind(auditQueue, "order.*");

        PublishResult ok = topic.publish(new Message("order.created", "orderId=1001"), true);
        PublishResult unroutable = topic.publish(new Message("stock.low", "sku=9"), true);
        orderQueue.consume(Decision.NACK_TO_DLX);
        auditQueue.consume(Decision.ACK);

        assert ok.confirmed() && ok.routed() == 2 && !ok.returned();
        assert unroutable.confirmed() && unroutable.routed() == 0 && unroutable.returned();
        assert orderQueue.ready.isEmpty();
        assert auditQueue.ready.isEmpty();
        assert deadLetterQueue.ready.size() == 1;
        assert deadLetterQueue.ready.peek().body().equals("orderId=1001");

        System.out.println("publish order.created routed=" + ok.routed() + ", returned=" + ok.returned());
        System.out.println("publish stock.low routed=" + unroutable.routed() + ", returned=" + unroutable.returned());
        System.out.println("order.q=" + orderQueue.ready.size() + ", audit.q=" + auditQueue.ready.size() + ", order.dlq=" + deadLetterQueue.ready.size());
    }
}
